<template><view class="page"><view class="bar"><text @tap="back">‹</text><text>空间相册</text><text @tap="create">＋</text></view><scroll-view class="scroll" scroll-y refresher-enabled :refresher-triggered="refreshing" @refresherrefresh="load"><view class="content"><view v-if="loading" class="state">正在读取相册…</view><view v-else-if="!albums.length" class="state" @tap="create">还没有相册，点此新建一个。</view><view v-else class="grid"><view v-for="album in albums" :key="album.id" class="album" @tap="open(album)"><image v-if="normalizeAssetUrl(album.cover_url)" class="cover" :src="normalizeAssetUrl(album.cover_url)" mode="aspectFill" lazy-load/><view v-else class="cover placeholder">相</view><text class="name">{{ album.name }}</text><text class="meta">{{ album.photo_count || 0 }} 张照片</text></view></view></view></scroll-view></view></template>
<script>import{getAlbums,normalizeAssetUrl}from'../../services/api';export default{data(){return{spaceId:'',albums:[],loading:true,refreshing:false}},onLoad(q){this.spaceId=q.spaceId||'';this.load()},onShow(){if(this.spaceId&&!this.loading)this.load()},methods:{normalizeAssetUrl,async load(){try{const data=await getAlbums(this.spaceId);this.albums=Array.isArray(data)?data:[]}catch(e){this.albums=[]}finally{this.loading=false;this.refreshing=false}},create(){uni.navigateTo({url:'/pages/album-create/index?spaceId='+this.spaceId})},open(a){uni.navigateTo({url:'/pages/album-detail/index?spaceId='+this.spaceId+'&albumId='+a.id+'&name='+encodeURIComponent(a.name)})},back(){uni.navigateBack({delta:1})}}}</script>
<style scoped>.page{height:100vh;background:#f1eee5}.bar{height:calc(var(--status-bar-height) + 104rpx);padding:var(--status-bar-height) 28rpx 0;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;background:#fffdf8;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:28rpx;font-weight:700}.bar text:first-child,.bar text:last-child{width:60rpx;color:#1d6347;font-size:52rpx;line-height:52rpx}.bar text:last-child{text-align:right}.scroll{height:calc(100vh - var(--status-bar-height) - 104rpx)}.content{padding:28rpx}.state{padding:130rpx 30rpx;border-radius:30rpx;color:rgba(23,33,29,.48);background:#fffdf8;font-size:22rpx;text-align:center}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18rpx}.album{padding:13rpx;border-radius:26rpx;background:#fffdf8}.cover{width:100%;height:240rpx;border-radius:18rpx;background:#e4ecdf}.placeholder{display:flex;align-items:center;justify-content:center;color:#f7b84b;background:#163a2b;font-size:44rpx}.name,.meta{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.name{margin-top:14rpx;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:26rpx;font-weight:700}.meta{margin-top:7rpx;color:rgba(23,33,29,.45);font-size:18rpx}</style>
